// JAH demo program - run with: node demo.js (or paste into a browser console)
// Demo: Speech Recognition Engine - public implementations survey
(function(){'use strict';
var DATA={"label": "Speech Recognition Engine - public implementations survey", "frames": [{"t": 0, "v": 0}, {"t": 0.5, "v": 7}, {"t": 1, "v": 10}], "samples": [0, 0.25, 0.5, 0.75, 1.0]};

function at(t){var F=DATA.frames;
  if(t<=F[0].t)return F[0].v;
  for(var i=1;i<F.length;i++){if(t<=F[i].t){
    var k=(t-F[i-1].t)/(F[i].t-F[i-1].t);
    return F[i-1].v+(F[i].v-F[i-1].v)*k;}}
  return F[F.length-1].v;}
console.log('Keyframes ('+DATA.label+'):');
DATA.samples.forEach(function(t){console.log('  t='+t.toFixed(2)+' -> v='+at(t).toFixed(3));});
})();

// JAH demo program - run with: node demo.js (or paste into a browser console)
// Demo: Whisper - Speech Recognition Engine implementation spotlight
(function(){'use strict';
var DATA={"label": "Whisper - Speech Recognition Engine implementation spotlight", "freqs": [220, 330], "seconds": 0.02, "rate": 8000};

var n=Math.floor(DATA.seconds*DATA.rate),samples=[],peak=0,sum=0;
for(var i=0;i<n;i++){var t=i/DATA.rate,v=0;
  DATA.freqs.forEach(function(f){v+=Math.sin(2*Math.PI*f*t)/DATA.freqs.length;});
  samples.push(v);peak=Math.max(peak,Math.abs(v));sum+=v*v;}
var rms=Math.sqrt(sum/n);
console.log('Waveform ('+DATA.label+'): '+DATA.freqs.join('+')+' Hz, '+DATA.seconds+'s @ '+DATA.rate+'Hz');
console.log('samples='+n+' peak='+peak.toFixed(3)+' rms='+rms.toFixed(3));
var bars='';for(var b=0;b<48;b++){var s2=samples[(b*n/48)|0];
  bars+=' .:-=+*#%@'[(Math.abs(s2)/ (peak||1)*8)|0];}
console.log('envelope: '+bars);
})();

